style.css:
@-moz-document domain("hh.ru"), domain("hh.kz"), domain("hh.uz"), domain("hh.by"), domain("rabota.by"), domain("headhunter.kg") {
:root { color-scheme: dark !important; }

  /* hh runs on the "Magritte"/"Bloko" token system: nearly every colour is a custom property, so remapping the
 light tokens reskins the UI; the element-level rules below back up the rest. Core tokens are remapped for
 every live version suffix (v21 / v24 / bloko v0-12-2). */
  html, body, body.magritte-hh-day-theme, :root {
    /* surfaces */
    --magritte-color-background-primary-v24-7-0: #14181d;
    --magritte-color-background-primary-v21-1-0: #14181d;
    --magritte-color-background-secondary-v24-7-0: #1c2128;
    --magritte-color-background-secondary-v21-1-0: #1c2128;
    --magritte-color-background-tertiary-v24-7-0: #21262d;
    --magritte-color-background-tertiary-v21-1-0: #21262d;
    /* primary text */
    --magritte-color-text-primary-v24-7-0: #e6edf3;
    --magritte-color-text-primary-v21-1-0: #e6edf3;
    /* secondary / tertiary text */
    --magritte-color-text-secondary-v24-7-0: #8b949e;
    --magritte-color-text-secondary-v21-1-0: #8b949e;
    --magritte-color-text-tertiary-v24-7-0: #6e7681;
    --magritte-color-text-tertiary-v21-1-0: #6e7681;
    /* accent text / links */
    --magritte-color-text-accent-v24-7-0: #5fb0e6;
    --magritte-color-text-accent-v21-1-0: #5fb0e6;
    --magritte-color-text-accent-secondary-v24-7-0: #5fb0e6;
    --magritte-color-text-accent-secondary-v21-1-0: #5fb0e6;
    --magritte-color-icon-accent-v24-7-0: #5fb0e6;
    --magritte-color-icon-accent-v21-1-0: #5fb0e6;
    /* strokes / borders */
    --magritte-color-stroke-neutral-v24-7-0: #2d333b;
    --magritte-color-stroke-neutral-v21-1-0: #2d333b;
    --magritte-color-stroke-neutral-heavy-v24-7-0: #3a424c;
    --magritte-color-stroke-neutral-heavy-v21-1-0: #3a424c;
    /* component surfaces (cards, inputs, dropdowns, modals, tooltips) */
    --magritte-color-component-card-background-primary-v24-7-0: #1c2128;
    --magritte-color-component-modal-background-content-v24-7-0: #1c2128;
    --magritte-color-component-drop-background-content-v24-7-0: #1c2128;
    --magritte-color-component-tag-background-on-surface-neutral-v24-7-0: #21262d;
    --magritte-color-component-input-background-field-v24-7-0: #1c2128;
    --magritte-color-component-input-background-state-field-hovered-v24-7-0: #1c2128;
    --magritte-color-component-input-background-state-field-focused-v24-7-0: #1c2128;
    --magritte-color-component-input-background-state-field-invalid-v24-7-0: #1c2128;
    --magritte-color-component-input-background-state-field-disabled-v24-7-0: #181d23;
    --magritte-color-component-tooltip-background-content-v21-1-0: #21262d;
    --magritte-color-component-tooltip-background-content-v24-7-0: #21262d;
    /* legacy bloko */
    --bloko-color-special-tertiary: #8b949e;
    --bloko-color-special-secondary: #c4cdd6;

    /* --- Magritte v24-7-2 (current live suffix) --------------------------- hh re-suffixed the token set;
 without this the icons render #000, drops/inputs paint #fff, and buttons fall back to light. */
    /* surfaces */
    --magritte-color-background-primary-v24-7-2: #14181d;
    --magritte-color-background-body-v24-7-2: #14181d;
    --magritte-color-background-secondary-v24-7-2: #1c2128;
    --magritte-color-background-tertiary-v24-7-2: #21262d;
    --magritte-color-background-state-primary-hovered-v24-7-2: #14181d;
    --magritte-color-background-state-primary-pressed-v24-7-2: #14181d;
    --magritte-color-background-state-secondary-hovered-v24-7-2: #21262d;
    --magritte-color-background-state-secondary-pressed-v24-7-2: #2d333b;
    --magritte-color-background-state-tertiary-hovered-v24-7-2: #2d333b;
    --magritte-color-background-state-tertiary-pressed-v24-7-2: #2d333b;
    /* tinted "secondary" surfaces (badge / callout backdrops) */
    --magritte-color-background-accent-secondary-v24-7-2: #1f3550;
    --magritte-color-background-positive-secondary-v24-7-2: #16301f;
    --magritte-color-background-negative-secondary-v24-7-2: #3a231e;
    --magritte-color-background-warning-secondary-v24-7-2: #33261a;
    --magritte-color-background-special-secondary-v24-7-2: #241d33;
    --magritte-color-background-dreamy-secondary-v24-7-2: #16303c;
    --magritte-color-background-lovely-secondary-v24-7-2: #3a1c24;
    --magritte-color-background-vivid-secondary-v24-7-2: #332c14;
    /* text */
    --magritte-color-text-primary-v24-7-2: #e6edf3;
    --magritte-color-text-secondary-v24-7-2: #8b949e;
    --magritte-color-text-dense-v24-7-2: #c4cdd6;
    --magritte-color-text-accent-v24-7-2: #5fb0e6;
    --magritte-color-text-accent-secondary-v24-7-2: #5fb0e6;
    --magritte-color-text-state-primary-hovered-v24-7-2: #ffffff;
    --magritte-color-text-state-primary-pressed-v24-7-2: #e6edf3;
    /* icons — icon-primary shipped #000: black glyphs on every dark surface */
    --magritte-color-icon-primary-v24-7-2: #c4cdd6;
    --magritte-color-icon-secondary-v24-7-2: #8b949e;
    --magritte-color-icon-accent-v24-7-2: #5fb0e6;
    --magritte-color-icon-accent-secondary-v24-7-2: #5fb0e6;
    --magritte-color-icon-state-primary-hovered-v24-7-2: #e6edf3;
    --magritte-color-icon-state-primary-pressed-v24-7-2: #ffffff;
    --magritte-color-icon-state-secondary-hovered-v24-7-2: #c4cdd6;
    /* strokes */
    --magritte-color-stroke-neutral-v24-7-2: #2d333b;
    --magritte-color-stroke-neutral-heavy-v24-7-2: #3a424c;
    --magritte-color-stroke-phantom-v24-7-2: #2d333b;
