    --magritte-color-component-button-background-neutral-secondary-v24-7-2: #21262d;
    --magritte-color-component-button-background-accent-v24-7-2: #2f81f7;
    --magritte-color-component-button-background-accent-secondary-v24-7-2: #1f3550;
    --magritte-color-component-button-background-state-neutral-hovered-v24-7-2: #3a424c;
    --magritte-color-component-button-background-state-neutral-pressed-v24-7-2: #3a424c;
    --magritte-color-component-button-background-state-neutral-secondary-hovered-v24-7-2: #2d333b;
    --magritte-color-component-button-background-state-neutral-secondary-pressed-v24-7-2: #2d333b;
    --magritte-color-component-button-background-state-accent-hovered-v24-7-2: #4c9bff;
    --magritte-color-component-button-background-state-accent-pressed-v24-7-2: #4c9bff;
    --magritte-color-component-button-background-state-accent-secondary-hovered-v24-7-2: #24406040;
    --magritte-color-component-button-text-neutral-secondary-v24-7-2: #e6edf3;
