    --magritte-color-component-chips-background-unchecked-neutral-secondary-v24-7-2: #21262d;
    --magritte-color-component-chips-background-unchecked-accent-v24-7-2: #1f3550;
    --magritte-color-component-chips-background-checked-neutral-v24-7-2: #1f3550;
    --magritte-color-component-chips-background-checked-neutral-secondary-v24-7-2: #21262d;
    --magritte-color-component-chips-background-checked-accent-v24-7-2: #2f81f7;
    --magritte-color-component-chips-background-state-unchecked-neutral-hovered-v24-7-2: #2d333b;
    --magritte-color-component-chips-background-state-unchecked-neutral-secondary-hovered-v24-7-2: #2d333b;
    --magritte-color-component-chips-background-state-unchecked-accent-hovered-v24-7-2: #24406b;
    --magritte-color-component-chips-background-state-checked-neutral-hovered-v24-7-2: #24406b;
    --magritte-color-component-chips-background-state-checked-neutral-secondary-hovered-v24-7-2: #2d333b;
    --magritte-color-component-chips-text-unchecked-neutral-v24-7-2: #c4cdd6;
    --magritte-color-component-chips-text-unchecked-neutral-secondary-v24-7-2: #c4cdd6;
    --magritte-color-component-chips-text-unchecked-accent-v24-7-2: #5fb0e6;
    --magritte-color-component-chips-text-checked-neutral-secondary-v24-7-2: #e6edf3;
    --magritte-color-component-chips-text-state-unchecked-neutral-hovered-v24-7-2: #e6edf3;
    --magritte-color-component-chips-text-state-unchecked-neutral-secondary-hovered-v24-7-2: #e6edf3;
    --magritte-color-component-chips-text-state-checked-neutral-secondary-hovered-v24-7-2: #e6edf3;
    --magritte-color-component-chips-text-state-unchecked-accent-hovered-v24-7-2: #9bd4ff;
    --magritte-color-component-chips-icon-unchecked-neutral-v24-7-2: #c4cdd6;
    --magritte-color-component-chips-icon-unchecked-accent-v24-7-2: #5fb0e6;
    --magritte-color-component-chips-icon-checked-neutral-secondary-v24-7-2: #e6edf3;
    --magritte-color-component-chips-icon-state-unchecked-neutral-hovered-v24-7-2: #e6edf3;
