    --magritte-color-component-checkable-icon-state-unchecked-hovered-v24-7-2: #2d333b;
    --magritte-color-component-checkable-card-background-unchecked-v24-7-2: #1c2128;
    --magritte-color-component-checkable-card-background-state-unchecked-hovered-v24-7-2: #21262d;
