  /* ---- Base surfaces ---- */
  html, body { background-color: #14181d !important; color: #c4cdd6 !important; }
  #HH-React-Root, #a11y-root, .HH-Supernova-MainContent, .main-content,
  [data-qa="main-content"], .supernova-content, .HH-MainContent-Wrapper,
  .bloko-column, [class*="layout"], [class*="content-wrapper"],
  [class*="magritte-page"], main {
    background-color: transparent !important; }

  /* ---- Soften all default light borders ---- */
  * { border-color: #2d333b !important; }

  /* ---- Header / global nav (supernova) ---- */
  .supernova-navi, .supernova-navi-wrapper, .supernova-navi-container,
  .supernova-navi-wrapper_theme-desktop-light, [class*="supernova-navi-wrapper"],
  .HH-Supernova-Header, .supernova-search-wrapper {
    background-color: #0d1117 !important; border-color: #2d333b !important; }
  .supernova-navi { border-bottom: 2px solid #c33c4a !important; } /* hh red, toned for dark */
  .supernova-navi a, .supernova-navi-item, .supernova-link,
  [data-qa^="mainmenu_"], [data-qa="allServices-button"], [data-qa="help-button"],
  [data-qa="moreItems-button"], [data-qa="geoSwitcher-button"],
  .supernova-navi-item-inner, .supernova-dropdown-anchor {
    color: #e6edf3 !important; }
  .supernova-navi a:hover, .supernova-navi-item:hover { color: #ffffff !important; }
  .supernova-dropdown, .supernova-dropdown-section, .supernova-dropdown-list,
  [class*="supernova-dropdown"], .supernova-overlay {
    background-color: #1c2128 !important; border-color: #2d333b !important; }
  /* `supernova-dropdown-anchor` is the TRIGGER in the header bar, not the panel, natively transparent — the
 prefix match above filled it, leaving a lighter square behind "Ищу работу" at 390px. Panels keep their
 surface. */
  .supernova-dropdown-anchor {
    background-color: transparent !important; }
  /* The header role menu ("Ищу работу"/"Ищу сотрудника") portals into a legacy `bloko-drop_theme-light` panel
 with a hardcoded WHITE surface. The dark supernova sections cover it on desktop, but at 390px the panel
 goes full-height and its white shows through the arrow notch. Dark it + the ::after divider strip
 (#eef1f7), which an element-bg scan misses. */
  .bloko-drop, [class*="bloko-drop"] {
    background-color: #1c2128 !important; border-color: #2d333b !important; }
  .supernova-dropdown-section::after, .supernova-dropdown-section::before {
    background-color: #2d333b !important; }
  /* the menu's pointer is a zero-size ::after whose border-bottom-color IS the arrow — `* { border-color }`
 never reaches pseudo-elements. */
  .supernova-dropdown-arrow::after {
    border-bottom-color: #1c2128 !important; }
  .supernova-dropdown-arrow::before {
    border-bottom-color: #2d333b !important; }
  /* logo: keep its own colours, never tint the image */
  [data-qa="supernova-logo"], [data-qa="supernova-logo"] * { color: inherit; }

  /* ---- Generic Magritte cards / surfaces (hashed suffix → prefix match) ---- */
  [class*="magritte-card"], [class*="magritte-paper"],
  [class*="magritte-segments-container"], [class*="magritte-segment"],
  [class*="magritte-position-container"],
  [data-qa="vacancy-item-desktop"], [data-qa="company-item-desktop"],
  [data-qa="remote-item-desktop"], [data-qa="professions-item-desktop"],
  [data-qa="vacancy-serp__vacancy"], [class*="vacancy-card"],
  [class*="serp-item"], [class*="-card-"] {
    background-color: #1c2128 !important; border-color: #2d333b !important; }
  [class*="magritte-card-style-special"],
  [class*="magritte-card-style-secondary"],
  [class*="magritte-segment"][class*="selected"] {
    background-color: #21262d !important; }
  /* Only cards flagged `magritte-card-hover-enabled` answer the pointer natively (a lifted shadow); the static
 vacancy/employer info cards must not. */
  [class*="magritte-card-hover-enabled"]:hover, [data-qa="vacancy-serp__vacancy"]:hover {
    background-color: #21262d !important; }
  /* While new results load, the SERP puts `search-loading-container--<hash>` on the list and every card gets a
 full-size #f1f1f1 opacity-.5 ::after veil — over dark cards that washes the list light grey on every
 filter/sort/pager action. Transient + pseudo-painted: no load-time scan reaches it. Base value so the veil
 reads as a dim, the site's intent. */
  [class*="search-loading-container"] [class*="loading-target"]::after {
    background-color: #14181d !important; }

  /* ---- Employer "chameleon" branded templates ---- */
  /* Two chameleon naming conventions ship: hyphen (tmpl-hh-*) and UNDERSCORE (tmpl_hh_*, e.g. the Газпромбанк
 page's #eaf9ff shell + pure-white award cards). Both must be darkened or our light body text reads
 light-on-light-blue. */
  [class*="tmpl-hh-wrapper"], [class*="tmpl-hh-facts"], [class*="tmpl-hh-banner"],
  [class*="tmpl-hh-offers"], [class*="tmpl-hh-find"], [class*="tmpl-hh-reviews"],
  [class*="tmpl-hh"], [class*="tmpl_hh"],
  [class*="with-top-image"], [class*="employer-tabs-wrapper"] {
    background-color: #1c2128 !important; border-color: #2d333b !important; }
  [class*="tmpl-hh"] *, [class*="tmpl_hh"] * { color: #c4cdd6 !important; }
  [class*="tmpl-hh"] h1, [class*="tmpl-hh"] h2, [class*="tmpl-hh"] h3,
  [class*="tmpl_hh"] h1, [class*="tmpl_hh"] h2, [class*="tmpl_hh"] h3 { color: #e6edf3 !important; }
  /* Chameleon CTA button (`tmpl-hh-footer__link`): the employer's brand colour as a solid INLINE fill (e.g.
 rgb(255,0,2) + white label). The blanket bg rule repainted it the card colour and `* { border-color }`
 erased the border — a ghost outline. The hue can't be recovered and employer CSS is unbounded, so give it
 the accent surface: a button on ANY employer page. Scoped to `footer__link` only — a bare `__link` would
 box plain TEXT links on uninspectable templates. Other chameleon CTAs stay flattened (not a regression). */
  a[class*="tmpl-hh"][class*="footer__link"],
  a[class*="tmpl_hh"][class*="footer__link"] {
    background-color: #2f81f7 !important; border-color: #2f81f7 !important; }
  /* the CTA's own label/icon spans carry tmpl-hh classes too, so the blanket painted each a card-coloured slab
 across the button. Clear them. */
  a[class*="tmpl-hh"][class*="footer__link"] *,
  a[class*="tmpl_hh"][class*="footer__link"] * {
    background-color: transparent !important; }
  a[class*="tmpl-hh"][class*="footer__link"],
  a[class*="tmpl_hh"][class*="footer__link"],
  a[class*="tmpl-hh"][class*="footer__link"] *,
  a[class*="tmpl_hh"][class*="footer__link"] * {
    color: #ffffff !important; }
  /* The chameleon CONTENT block (tmpl_hh_content) also carries an employer background-IMAGE — a near-white JPG
 painting OVER our background-color, so our light body text sits on near-white → unreadable (bg-COLOR scans
 blind). Drop the image on the text block ONLY; the head banner / footer slider JPGs are dark with baked-in
 white text and keep theirs. */
  [class*="tmpl_hh_content"], [class*="tmpl-hh-content"] {
    background-image: none !important; }
  /* Chameleon template-builder section widgets (the "Наша миссия" mission and "projects" blocks) paint a
 full-panel LIGHT ::before (#f2f3f7) behind the section. The blanket tmpl_hh rule darkens the element, never
 the pseudo — the band stayed near-white under our light body text, and bg-COLOR scans are blind to it. Dark
 to the page base so the value cards read elevated. */
  [class*="tmpl_hh_mission"]::before, [class*="tmpl_hh_projects"]::before {
    background-color: #14181d !important; }
  /* The constructor "geography" widget's Russia map is an INLINE svg of 7 macro-region paths, each
 `fill="#E3E6E9"` — a ~850x440 near-white slab. Exact-value match is deliberate: it hits only the default
 grey, so an employer recolour survives. Region labels are pills painted #1c2128, so the land must stay
 clearly lighter; paths carry no stroke. */
  [class*="tmpl_hh_geo"] svg path[fill="#E3E6E9"] {
    fill: #3a424c !important; }
  /* Constructor widgets stack decorative artwork in a DEDICATED layer element (`tmpl_hh_<widget>__object(s)` /
 `__bg`): position:absolute, pointer-events:none, natively transparent, z-index:20 ABOVE the `__content`
 layer. Opaque it is a solid sheet over the whole section: everything under it disappears
 (hh.ru/employer/3529 carries two). Audit-proof — buried text keeps correct colours, the cover hit-tests as
 absent, its bg is a legitimate theme value. Two attribute selectors (0,2,0) outrank the blanket. */
  [class*="tmpl_hh"][class*="__object"], [class*="tmpl-hh"][class*="__object"],
  [class*="tmpl_hh"][class*="__bg"], [class*="tmpl-hh"][class*="__bg"] {
    background-color: transparent !important; }
  /* Newer constructor "О компании" pages: a hardcoded WHITE panel — our light body text reads light-on-light.
 Dark the widget; text already maps grey. */
  [class*="employer-constructor-widget"] {
    background-color: #1c2128 !important; border-color: #2d333b !important; }
  /* The chameleon nav bar (tmpl_hh_navigation) is a swiper of section links; each chevron button is a bare
 class-LESS <span> with a hardcoded LIGHT #e2e5eb square the blanket rule never reaches — three bright 40px
 glares, caught by smallLight (scan floor is >32px). Dark the square; its chevron is an hhcdn SVG (#626C77,
 white on current) that reads on dark. */
  li[class*="tmpl_hh_navigation__item"] > span {
    background-color: #21262d !important; }
  /* Employers highlight phrases inside chameleon blocks with a bare class-LESS inline tag carrying a pale
 employer-stylesheet fill (e.g. the "well-being-программа" pills at #f0f0ff). The blanket
 `[class*="tmpl-hh"]` rule only reaches tmpl-CLASSed tags, so these keep the pale fill under our light text.
 `:not([class])` keeps this to bare inline tags — tmpl-classed spans (captions/headings with dark boxes over
 photos) and the nav chevron above stay untouched. */
  [class*="tmpl-hh"] span:not([class]), [class*="tmpl_hh"] span:not([class]),
  [class*="tmpl-hh"] strong:not([class]), [class*="tmpl_hh"] strong:not([class]),
  [class*="tmpl-hh"] b:not([class]), [class*="tmpl_hh"] b:not([class]),
  [class*="tmpl-hh"] em:not([class]), [class*="tmpl_hh"] em:not([class]) {
    background-color: transparent !important; }
  /* A chameleon tile's headline sits in a tmpl-classed element — the blanket surface rule gives it a dark plate
 — but its body copy is a bare class-LESS <p> the blanket never matches. The tile's own surface is an
 employer-uploaded JPG painting OVER our background-color, so the paragraph is our light grey on near-white
 art while bg-COLOR scans read #1c2128. Give the <p> the same plate; on a genuinely dark tile the plate
 matches its container. */
  [class*="tmpl-hh"] p:not([class]), [class*="tmpl_hh"] p:not([class]) {
    background-color: #1c2128 !important; }
  /* The "benefits" widget draws each headline as GRADIENT TEXT (-webkit-background-clip: text, transparent
 text-fill), so neither the ink rule nor a bg plate reaches the glyphs — the black end of the ramp vanishes
 on the dark tile. Turn the clip off so the plate is a plate again, and ink it like the paragraph beside it. */
  [class*="tmpl_hh_benefits__subtitle"], [class*="tmpl-hh-benefits__subtitle"] {
    -webkit-background-clip: border-box !important;
    background-clip: border-box !important;
    background-image: none !important;
    background-color: #1c2128 !important;
    color: #7be8d8 !important; -webkit-text-fill-color: #7be8d8 !important; }
  /* The "workers" slider's prev/next arrows are class-less <img> chevrons (black strokes, transparent) inside a
 box the surface rule paints dark; the box holds only the glyph, so a filter is safe. */
  [class*="tmpl_hh_workers__arrow"] img, [class*="tmpl-hh-workers__arrow"] img {
    filter: invert(0.8) !important; }
  /* SERP "branded snippet" cards ship the employer's brand colour as an INLINE background-color (or, newer, a
 saturated linear-gradient background-IMAGE painting OVER our background-color) on the wrapper; the inner
 content is a dark magritte-card, so the frame + illustration column glare light. Dark the wrapper, drop the
 image; match the base wrapper only (`branded-snippet-picture--`/`-logo--` never contain the double dash) so
 the illustration + logo stay untouched. */
  [class*="branded-snippet--"] {
    background-color: #1c2128 !important; background-image: none !important; }

  /* ---- Typography ---- */
  h1, h2, h3, h4, h5, h6, [class*="magritte-title"], [class*="magritte-text"][class*="primary"],
  [data-qa="title"], [data-qa$="-title"], [data-qa="company-header-title-name"],
  [data-qa="bloko-header-1"], [data-qa="bloko-header-2"], [data-qa="bloko-header-3"] {
    color: #e6edf3 !important; }
  p, li, span:not(.metro-point), dd, dt, td, th, caption, label, figcaption, time, small, b, strong, em,
  div, [class*="magritte-text"] {
    color: #c4cdd6 !important; }
  /* metro-line dots in vacancy addresses: an empty <span class="metro-point"> whose inline line colour paints a
 ::before "●". The blanket span rule flattened every dot to grey, erasing the line coding — excluding it
 lets the inline colour win. */
  /* secondary / muted text used widely (#768694, #6a7885, #aabbca, #1b1b1b legacy) */
  [class*="secondary"], [class*="muted"], [data-qa$="-secondary"],
  [data-qa="vacancy-serp__vacancy-address"], [data-qa="vacancy-label-remote"],
  .bloko-text_tertiary, .supernova-navi-search-text {
    color: #8b949e !important; }

  /* ---- Links: hh blue is too dark on dark → readable blue ---- A link's label is usually an inner <span>
 (magritte-text). Two of our rules outrank a plain `a span` (0-0-2) on it: the blanket
 `[class*="magritte-text"]` (0-1-0) and `span:not(.metro-point)` (0-1-1). Every span-labelled link rendered
 body-grey — no link affordance left. Match the blanket's shape so the link arm wins on the span; rules that
 must beat this carry the same `:not(.metro-point)` to clear 0-1-2. */
  a, a span:not(.metro-point), .bloko-link, [class*="magritte-link"], [data-qa$="-link"] {
    color: #5fb0e6 !important; }
  a:hover, .bloko-link:hover, [class*="magritte-link"]:hover { color: #9bd4ff !important; }
  /* …the hover arm only repaints the <a>; the words are in an inner span the resting arm pins. Kept at `span`
 (no `:not()`) on purpose: the extra 0-0-1 of `:not(.metro-point)` would outrank the button-label and
 muted-metadata arms below, lighting a CTA's white label and card metadata blue on hover. At this weight
 those arms still win; link families needing their own hover carry one beside the resting rule. */
  a:hover span, [class*="magritte-link"]:hover span { color: #9bd4ff !important; }
  /* `magritte-link` is a BUTTON component ("Развернуть" expanders), so `a span:not(.metro-point)` never reaches
 its label — the accent link read as plain prose (chroma: native #0070ff → grey). Colour the ACCENT
 variant's own text/icon spans blue; the NEUTRAL variant (footer/nav) is deliberately primary/grey.
 Compounded with `magritte-link___` to reach 0-3-1: an expander inside a `magritte-text_style-secondary`
 block is also matched by the muted rule below at 0-2-1, which comes later and would otherwise win. */
  [class*="magritte-link___"][class*="magritte-link_style_accent"] span:not(.metro-point),
  [class*="magritte-link___"][class*="magritte-link_style_accent"] [class*="magritte-text"]:not(.metro-point) {
    color: #5fb0e6 !important; }
  [class*="magritte-link___"][class*="magritte-link_style_accent"]:hover span {
    color: #9bd4ff !important; }
  /* Magritte marks muted metadata `magritte-text_style-secondary`, but the words often live in a bare
 class-LESS child span. Inside an <a> the link arm (0-1-2) outranks the muted rule (0-1-0), so a link-bodied
 tile's "40140 вакансий" turned blue beside grey siblings (native #768694). Keep the muted grey. */
  [class*="magritte-text_style-secondary"] span:not(.metro-point) {
    color: #8b949e !important; }
  /* header nav items are anchors whose label is a span: they must stay primary text, not turn link-blue */
  .supernova-navi a span:not(.metro-point),
  .supernova-navi-item span:not(.metro-point) {
    color: #e6edf3 !important; }
  .supernova-navi a:hover span, .supernova-navi-item:hover span {
    color: #ffffff !important; }
  /* card/headline links should read as bright primary text, blue on hover */
  [data-qa="serp-item__title"], [data-qa="serp-item__title-text"],
  [data-qa="vacancy-serp__vacancy-title"], [data-qa="bloko-header-2"] a,
  [data-qa="vacancy-company-name"], [data-qa="company-header-title-name"] a {
    color: #e6edf3 !important; }
  [data-qa="serp-item__title"] span:not(.metro-point),
  [data-qa="vacancy-serp__vacancy-title"] span:not(.metro-point),
  [data-qa="vacancy-company-name"] span:not(.metro-point) {
    color: #e6edf3 !important; }
  [data-qa="serp-item__title"]:hover, [data-qa="vacancy-serp__vacancy-title"]:hover,
  [data-qa="serp-item__title"]:hover span, [data-qa="vacancy-serp__vacancy-title"]:hover span {
    color: #5fb0e6 !important; }

  /* ---- Search block (home + supernova + SERP) ---- */
  .supernova-search, [data-qa="supernova-search"], .HH-SupernovaSearch,
  [data-qa="search-input"], [class*="magritte-input"], input, textarea, select,
  [data-qa="vacancysearch__keywords-input"], [data-qa="advanced-search"] {
    background-color: #1c2128 !important; color: #e6edf3 !important;
    border-color: #2d333b !important; }
  /* On pages whose header carries the collapsed search entry, `supernova-search` is the nav ITEM's label span
 ("Поиск" + magnifier), natively bare — the field arm stamps a tight box around the word. Real inputs stay
 covered by the `input` arm. */
  span[data-qa="supernova-search"] { background-color: transparent !important; }
  /* hh paints the typed value with -webkit-text-fill-color (black), which overrides `color` → black text on the
 dark field. Repaint the fill on the real controls only (NOT the wrappers, whose fill would recolour the
 floating placeholder labels too). */
  input, textarea { -webkit-text-fill-color: #e6edf3 !important; }
  /* Magritte text fields layer the <input> ON TOP of a floating <label> that is the placeholder (hero phone
 CTA, global search, salary filters). An OPAQUE bg on the input hides the label — keep the input transparent
 and let its shell carry the dark surface; the value stays bright, label + value-ghost become the muted
 placeholder. */
  input[class*="magritte-field"], textarea[class*="magritte-field"] {
    background-color: transparent !important; color: #e6edf3 !important; }
  [class*="magritte-content-container"], [class*="magritte-hint-container"] {
    background-color: #1c2128 !important; }
  /* The text field's OUTER wrapper (`magritte-input___` div) is natively transparent; the rounded shell is the
 inner `magritte-position-container`. Painting the wrapper draws a square slab extending below the field,
 boxing the helper/error row. Keep the wrapper bare — real inputs are still covered by the `input, textarea,
 select` arm. */
  div[class*="magritte-input___"] { background-color: transparent !important; }
  label[class*="magritte-label"], [class*="magritte-value-ghost"] {
    color: #8b949e !important; }
  input::placeholder, textarea::placeholder,
  [class*="magritte-input"] ::placeholder, .magritte-input___Vul7O ::placeholder {
    color: #8b949e !important; -webkit-text-fill-color: #8b949e !important; opacity: 1 !important; }
  /* the home page big segmented search wrapper */
  [data-qa="userTypeSegmented"] {
    background-color: transparent !important; }
  [data-qa="userTypeSegmentedApplicant"], [data-qa="userTypeSegmentedEmployer"] {
    color: #e6edf3 !important; }

  /* ---- Buttons ---- */
  .bloko-button, [class*="magritte-button"], button[class*="button"],
  [data-qa="search-button"], [data-qa="signup"], [data-qa="login"] {
    border-color: #2d333b !important; }
  /* secondary / tertiary buttons → dark surface */
  [class*="magritte-button-style-secondary"],
  [class*="magritte-button-style-tertiary"],
  .bloko-button_kind-default, .bloko-button:not([class*="primary"]) {
    background-color: #21262d !important; color: #e6edf3 !important; }
  [class*="magritte-button-style-secondary"]:hover,
  .bloko-button_kind-default:hover { background-color: #2d333b !important; }
  /* Carousel arrows ("Компании для вас" rails) render a round Magritte "secondary background" surface
 (magritte-background-style-secondary___) the suffix remap misses — a bright white 40px circle on the dark
 SERP. Audit-blind (small control, under the scan floor). Dark it to the elevated card colour; the chevron
 already maps #8b949e. */
  [class*="magritte-background-style-secondary"] {
    background-color: #21262d !important; }
  /* primary CTA → hh blue accent, kept vivid. NB: don't paint the <button> of the current Magritte component —
 its rounded surface is the inner `-view` span, a bg here leaks a square blue slab past the corners. The
 bloko arm is compounded with `.bloko-button` to clear 0-2-0: the blanket reset matches it as
 `button[class*="button"]` (0-1-1) and would ring the blue pill ("Понятно") in grey. */
  [class*="magritte-button-style-primary"],
  .bloko-button.bloko-button_kind-primary {
    background-color: #2f81f7 !important; color: #ffffff !important;
    border-color: #2f81f7 !important; }
  [class*="magritte-button-style-primary"]:hover,
  .bloko-button_kind-primary:hover { background-color: #4c9bff !important; }
  /* Current Magritte button: the visible surface moved onto an inner `magritte-button-view` span fed by the
 tokens above, and variants were renamed (`magritte-button_mode-*` / `_style-*`). Label/icon colour must
 follow the variant or the blanket `span` / `a span` rules paint a blue CTA's white label light-grey. */
  [class*="magritte-button_style-accent"][class*="magritte-button_mode-primary"] span,
  [class*="magritte-button_style-special"][class*="magritte-button_mode-primary"] span,
  [class*="magritte-button_style-positive"][class*="magritte-button_mode-primary"] span,
  [class*="magritte-button_style-negative"][class*="magritte-button_mode-primary"] span {
    color: #ffffff !important; }
  /* `:not(.metro-point)` here is a specificity brace, not a filter: an anchor- button's label must outrank the
 link rule's `a span:not(.metro-point)` or a neutral CTA reads link-blue instead of primary text. */
  [class*="magritte-button_style-neutral"] span:not(.metro-point) {
    color: #e6edf3 !important; }
  [class*="magritte-button_style-accent"][class*="magritte-button_mode-secondary"] span,
  [class*="magritte-button_style-accent"][class*="magritte-button_mode-tertiary"] span {
    color: #5fb0e6 !important; }
  /* "constant"/"inverse" buttons live on hh's own always-black surfaces (region tooltip, image overlays):
 primary variant is a WHITE pill that must keep dark text; secondary/tertiary sit on #303030 and keep white.
 The blanket `span` colour would light the white pill's label. A `span` arm alone is not enough: a rich CTA
 (hh PRO hero) renders its label as `magritte-text` DIVs and its crown as an inline SVG — the div /
 magritte-text / svg arms clear 0-2-0. */
  [class*="magritte-button_style-constant"][class*="magritte-button_mode-primary"] span,
  [class*="magritte-button_style-constant"][class*="magritte-button_mode-primary"] div,
  [class*="magritte-button_style-constant"][class*="magritte-button_mode-primary"] svg,
  [class*="magritte-button_style-constant"][class*="magritte-button_mode-primary"] [class*="magritte-text"] {
    color: #111111 !important; }
  [class*="magritte-button_style-inverse"][class*="magritte-button_mode-primary"] span,
  [class*="magritte-button_style-inverse"][class*="magritte-button_mode-primary"] div,
  [class*="magritte-button_style-inverse"][class*="magritte-button_mode-primary"] svg,
  [class*="magritte-button_style-inverse"][class*="magritte-button_mode-primary"] [class*="magritte-text"] {
    color: #0d1115 !important; }
  [class*="magritte-button_style-constant"][class*="magritte-button_mode-secondary"] span,
  [class*="magritte-button_style-constant"][class*="magritte-button_mode-tertiary"] span {
    color: #ffffff !important; }

  /* ---- Chips / filters / tags (search sidebar & SERP) ---- */
  [data-qa="chip"], [class*="magritte-chips"], [class*="magritte-chip"],
  [class*="bloko-tag"], [data-qa="serp__novafilter"], .novafilters,
  [class*="magritte-checkable-chips"] {
    background-color: #21262d !important; color: #c4cdd6 !important;
    border-color: #2d333b !important; }
  [class*="magritte-chips"][class*="checked"],
  [class*="magritte-chip"][class*="checked"] {
    background-color: #1f3550 !important; color: #e6edf3 !important; }
  [data-qa="advanced-filter"], [data-qa="serp__settings"],
  [data-qa="order-by-menu"], .supernova-filters {
    background-color: transparent !important; color: #c4cdd6 !important; }
  /* The SERP "+ Район / Метро / …" add-filter chips darken at the button level, but the inner content span
 (magritte-content___) ships a hardcoded WHITE fill on top → light-on-light. Audit-blind (32px, under the
 floor). Clear the inner fill so the dark chip shows through; label already maps light, checked chip keeps
 its blue surface. */
  [class*="magritte-chip"] [class*="magritte-content___"],
  [data-qa="chip"] [class*="magritte-content___"] {
    background-color: transparent !important; }
  /* …the RADIO chips in the mobile "Фильтры" sheet are the opposite shape: the <label> is transparent and that
 SAME inner span IS the pill — #f1f4f9 unchecked, #000 + white label checked. The rule above clears both, so
 every chip rendered one grey slab; state lives on a sibling `input:checked`, never a class, so no DOM scan
 sees the loss. Re-establish both states: `>` lifts the resting arm to 0-2-1, the `:checked` arm follows.
 Both arms stay anchored on `label[class*="magritte-chip___"] >` — `input:checked + content` alone also
 matches the /account/login role CARD and floods it blue. */
  label[class*="magritte-chip___"] > [class*="magritte-content___"] {
    background-color: #21262d !important; }
  label[class*="magritte-chip___"] > input:checked + [class*="magritte-content___"] {
    background-color: #2f81f7 !important; }
  label[class*="magritte-chip___"] > input:checked + [class*="magritte-content___"] [class*="magritte-text"] {
    color: #ffffff !important; }
  /* …and a filter chip must answer the pointer. Natively the surface lives on the inner span, but the rules
 above clear it and pin colour on the button, taking the hover cue with it. Give the button the lift back,
 one arm per state so checked still reads checked under the cursor. Anchored on `button`: the sheet's
 label-chips have their surfaces set above. */
  button[class*="magritte-chip___"]:not([class*="checked"]):hover {
    background-color: #2d333b !important; }
  button[class*="magritte-chip___"][class*="checked"]:hover {
    background-color: #24406b !important; }
  /* The employer landing hero's "Часто ищут" quick pills — a CSS-module `chips-item--<hash>` button with
 hardcoded `background-color:#fff` — stayed white under our lifted #e6edf3 label: white on white. Its own
 :hover already resolves the dark tertiary token, so only the resting state needed fixing. `data-qa` is the
 stable hook; the class arm covers the same node. */
  [data-qa="employer-index-search-frequently-item"],
  [class*="chips-item--"] {
    background-color: #2d333b !important; }
  [data-qa="employer-index-search-frequently-item"]:hover,
  [class*="chips-item--"]:hover {
    background-color: #3a424c !important; }
  /* On scroll the SERP filter-chip bar re-mounts as a FIXED glass strip (`sticky--<hash>`) with a hardcoded
 near-white `color(srgb 1 1 1/.68)` + blur — a white band under the dark chips. Absent at scroll 0, and the
 hashed class + srgb() make it audit-blind. Pin to the page base. */
  div[class*="sticky--"] {
    background-color: #14181d !important; }
  /* The EMPLOYER page's "Вакансии" tab runs the same stuck bar through a DIFFERENT module: resting
 `root--<hash>` is opaque rgb(255,255,255) from scroll 0; `root-transparent--<hash>` is ADDED past ~400px.
 Both need darkening, and a single-scroll probe sees only one half. A bare `root--` is generic CSS-module,
 so anchor on position: the bar is the only root-- grandchild of <main>. */
  main > div > div[class*="root--"],
  div[class*="root-transparent--"] {
    background-color: #14181d !important; }

  /* ---- Magritte tags: each style variant carries meaning ---- A tag is not a card, but the card rule painted
 every `magritte-tag` the card colour: neutral tags vanished into the card, positive ones ("Отклик без
 резюме") came out grey like the chip beside them. Give each variant its tinted surface, keep its label hue. */
  [class*="magritte-tag_style-neutral"] {
    background-color: #21262d !important; }
  [class*="magritte-tag_style-neutral"] [class*="magritte-tag__label"] {
    color: #c4cdd6 !important; }
  [class*="magritte-tag_style-positive"] {
    background-color: #16301f !important; }
  [class*="magritte-tag_style-positive"] [class*="magritte-tag__label"] {
    color: #57d98a !important; }
  [class*="magritte-tag_style-negative"] {
    background-color: #3a231e !important; }
  [class*="magritte-tag_style-negative"] [class*="magritte-tag__label"] {
    color: #ff8a7a !important; }
  [class*="magritte-tag_style-warning"] {
    background-color: #33261a !important; }
  [class*="magritte-tag_style-warning"] [class*="magritte-tag__label"] {
    color: #fdb972 !important; }
  [class*="magritte-tag_style-accent"] {
    background-color: #1f3550 !important; }
  [class*="magritte-tag_style-accent"] [class*="magritte-tag__label"] {
    color: #7cc3f0 !important; }
  [class*="magritte-tag_style-special"] {
    background-color: #241d33 !important; }
  [class*="magritte-tag_style-special"] [class*="magritte-tag__label"] {
    color: #c3a6f5 !important; }

  /* ---- Semantic text ---- `magritte-text_style-<style>` marks coloured labels (the /services "Популярное
 сейчас" purple #9054ea; positive/negative/warning statuses). The blanket typography rules greyed all of
 them. Keep each hue, lifted for dark. */
  [class*="magritte-text"][class*="_style-special"] { color: #c3a6f5 !important; }
  [class*="magritte-text"][class*="_style-positive"] { color: #57d98a !important; }
  [class*="magritte-text"][class*="_style-negative"] { color: #ff8a7a !important; }
  [class*="magritte-text"][class*="_style-warning"] { color: #fdb972 !important; }
  [class*="magritte-text"][class*="_style-accent"] { color: #5fb0e6 !important; }

  /* Resume cards stamp recency with `date-highlight--<hash>`, positive green (#10b55f) so a fresh CV stands
 out. The stamp sits inside a `magritte-text_style-secondary` block, so the muted rule (0-2-1) greyed every
 one. Restore the hue. The first arm ties at 0-2-1 and wins on order, so this block must stay BELOW it; the
 second arm is needed because the stamp splits its text ("Обновлено" + date in a bare child span) and hh
 paints BOTH green. */
  span[class*="date-highlight--"]:not(.metro-point),
  span[class*="date-highlight--"] span:not(.metro-point) {
    color: #57d98a !important; }

  /* ---- Semantic icons ---- Magritte marks meaning-bearing icons `magritte-icon_initial-<style>`; the muted
 rule above matches any class containing "secondary", so the GOLD employer-rating star
 (`…warning-secondary`) went caption-grey. Restore each semantic hue; a plain `initial-secondary` icon is
 genuinely neutral and stays grey. */
  svg[class*="magritte-icon_initial-warning"] { color: #fdb972 !important; }
  svg[class*="magritte-icon_initial-positive"] { color: #57d98a !important; }
  svg[class*="magritte-icon_initial-negative"] { color: #ff8a7a !important; }
  svg[class*="magritte-icon_initial-accent"] { color: #5fb0e6 !important; }

  /* ---- Filter select / "trigger" controls (sidebar dropdowns: schedule, working hours, payout period, etc. —
 shipped white) ---- */
  [class*="magritte-trigger"], [data-qa="magritte-select-activator"],
  [data-qa="trigger-root"], [data-qa^="filter-select-trigger"] {
    background-color: #1c2128 !important; color: #e6edf3 !important;
    border-color: #2d333b !important; }
  /* the open select / dropdown menu surface (portaled, must stay opaque dark; skip the invisible
 base/container/border wrappers) */
  [class*="magritte-drop___"], [class*="magritte-select-drop"],
  [class*="magritte-menu"] {
    background-color: #1c2128 !important; border-color: #2d333b !important; }
  /* Magritte modals/dialogs (newer component versions paint a hardcoded WHITE panel the token remap misses —
 e.g. the ccTLD "Выберите язык" language picker on hh.kz/uz/by). Keep them opaque dark + lift their close
 glyph. */
  [class*="magritte-modal"], [role="dialog"][class*="magritte"] {
    background-color: #1c2128 !important; border-color: #2d333b !important; }
  /* `magritte-modal-overlay` is the full-viewport SCRIM, not a panel; the prefix match above painted it OPAQUE
 — opening the "Фильтры" panel or a select modal replaced the page with a flat slab LIGHTER than the base.
 hh's scrim is dark translucent (rgba(32,38,43,.68)); keep that shape. Same 0-1-0 as the rule above — order
 decides, so stay below it. */
  [class*="magritte-modal-overlay"] {
    background-color: rgba(13, 17, 23, 0.72) !important; }
  [class*="magritte-modal"] [class*="magritte-modal-close"] svg,
  [class*="magritte-modal"] [class*="magritte-modal-close"] svg path {
    color: #c4cdd6 !important; fill: currentColor !important; }
  /* At 390px the login/signup flow opens as a FULL-SCREEN overlay whose backing layer (CSS-module
 `container--<hash> animated--<hash>`, position:fixed, whole viewport) ships a hardcoded WHITE surface. The
 dark card inside is inset ~16px, so a bright frame shows on every edge — exposed outright during the
 `animated--` open transition. Desktop never renders it (centred page there). Both hashed prefixes together
 match this overlay and nothing else. */
  div[class*="container--"][class*="animated--"] {
    background-color: #14181d !important; }
  /* The ccTLD "Выберите язык" picker (hh.kz/uz/by) was redesigned onto Magritte "nav-bar-panes": the close
 button is a light-glass (rgba(255,255,255,.68)) rounded square with a BLACK X, and the pane's
 "-pane-background" backing layer is hardcoded white. Audit-blind-ish (occluded backing, small control).
 Dark the glass + backing, lift the glyph. */
  [class*="magritte-pane-background"] {
    background-color: #1c2128 !important; }
  /* The mobile bottom-sheet's sticky header (SERP "Фильтры" title bar) is a hardcoded WHITE
 `magritte-background-container` — a bright strip over the dark sheet, our light title on it unreadable.
 Only exists while the sheet is open: no load-time scan reaches it. */
  [class*="magritte-background-container"] {
    background-color: #1c2128 !important; }
  [data-qa="select-modal-close"] [class*="magritte-view"] {
    background-color: #21262d !important; }
  [data-qa="select-modal-close"] svg,
  [data-qa="select-modal-close"] svg path {
    color: #c4cdd6 !important; fill: #c4cdd6 !important; }
  /* The `overlay-action` token is white on purpose (discs over photos / map tiles — see the token block). But
 in a Magritte ACTIONS nav bar (full-screen sheet headers, e.g. the phone search sheet's ✕) the same disc
 sits on dark chrome and our light glyph reads ~1.2:1. Scoped to the actions bar so the over-photo discs
 keep their white. */
  [class*="magritte-actions-container"] [class*="magritte-background-style-overlay-action"] {
    background-color: rgba(13, 17, 23, 0.72) !important; }

  /* ---- Auth form: phone calling-code box + neutral "show more" social aggregator ship WHITE (the aggregator's
 hh label is light-grey → unreadable on white). Dark them; individual OAuth buttons keep their brand white.
 ---- */
  [data-qa="magritte-phone-input-calling-code"],
  [class*="magritte-calling-code-input-container"],
  [data-qa="account-login-social-show-more"] {
    background-color: #21262d !important; border-color: #2d333b !important;
    color: #e6edf3 !important; }
  [data-qa="account-login-social-show-more"] span,
  [data-qa="magritte-phone-input-calling-code"] span {
    color: #e6edf3 !important; }
  /* the OAuth provider tiles (Sber ID / VK / …) are "inverse" buttons: their glyph is painted with the
 near-black inverse token and their tile is dark under this theme → dark-on-dark. The glyphs use
 fill="currentColor", so lifting `color` alone recolours them without flattening any brand logo that ships
 an explicit fill. */
  [class*="magritte-branded-button"] svg {
    color: #e6edf3 !important; }
  /* Every provider also ships SECONDARY/TERCIARY variants with a light neutral or brand-tint surface (#f1f1f1,
 #e6f1ff, …) — never declared, so e.g. the "Т-Банк" pill on the employer login/price pages rendered a
 near-white slab with a lifted label. Anchor on `-secondary___` / `-tertiary___`: the triple underscore is
 the Magritte module separator, so this matches ONLY the variants, never the PRIMARY buttons
 (`magritte-vk___`, `magritte-google___`, …) whose brand fills must survive. */
  [class*="magritte-branded-button"][class*="-secondary___"],
  [class*="magritte-branded-button"][class*="-tertiary___"] {
    background-color: #21262d !important; border-color: #2d333b !important; }
  [class*="magritte-branded-button"][class*="-secondary___"] span,
  [class*="magritte-branded-button"][class*="-tertiary___"] span {
    color: #e6edf3 !important; }

  /* ---- Checkboxes / radios: keep checked accent visible ---- */
  [data-qa="checkbox"], [class*="magritte-checkbox"], [class*="magritte-radio"] {
    border-color: #3a424c !important; }
  /* the control disc (magritte-radio___ / magritte-checkbox___, ~20px hash leaf) ships a WHITE unchecked fill.
 Audit-blind: the surface scan needs >120×40. Dark the disc to the card surface (#3a424c border reads as the
 empty ring); checked keeps the accent fill. */
  [class*="magritte-radio___"], [class*="magritte-checkbox___"] {
    background-color: #1c2128 !important; }
  /* A CHECKED control is natively bordered in the same accent as its fill (#0070ff); the blanket neutral stroke
 above flattened that ring to grey (chroma reports it as a lost accent). Gated on `input:checked +`, so the
 unchecked disc keeps its grey empty ring. */
  input:checked + [class*="magritte-radio___"],
  input:checked + [class*="magritte-checkbox___"] {
    background-color: #2f81f7 !important; border-color: #2f81f7 !important; }

  /* ---- Form validation: keep the error signal ---- The helper row ("Обязательное поле") is the error signal,
 negative token #ff4d3a. The blanket typography rules collapsed it to body grey — the red focus ring was the
 only cue left. Restore the site's red (4.5:1 on page base and card). */
  [class*="magritte-form-helper-error"],
  [class*="magritte-form-helper-error"] [class*="magritte-text"],
  [class*="magritte-form-helper-error"] [class*="magritte-form-helper-text-wrapper"] {
    color: #ff4d3a !important; }
  /* Older Magritte builds (the #cmsFrontendAppRoot lead form) render the same signal as `magritte-hint-error`,
 whose label is a style-primary text span. */
  [class*="magritte-hint-error"], [class*="magritte-hint-error"] [class*="magritte-text"] {
    color: #ff4d3a !important; }

  /* ---- Salary / compensation: keep its meaning, stay readable ---- */
  [data-qa="vacancy-serp__compensation"], [data-qa="vacancy-serp__vacancy-compensation"],
  [data-qa="vacancy-salary"], [class*="compensation"] {
    color: #d6dde3 !important; }

  /* ---- Vacancy detail page ---- */
  [class*="magritte-content-border-container"], .vacancy-section {
    background-color: #1c2128 !important; border-color: #2d333b !important; }
  [data-qa="vacancy-title"], [data-qa="vacancy-description"],
  [class*="vacancy-branded"], .bloko-tag-list,
  [data-qa="vacancy-view-employment-mode"] {
    color: #c4cdd6 !important; }
  [data-qa="vacancy-description"] * { color: inherit !important; }
  /* Branded ("chameleon") vacancy descriptions inject the employer's OWN stylesheet, which highlights section
 headers with a bright inline fill (e.g. #58ffff <strong> "ОБЯЗАННОСТИ:") — from the employer rule, not
 inline, so white-surface scans miss it; our light text then reads light-on-bright. Neutralise those fills
 within branded user content. NB: employer TEXT colours are deliberately NOT preserved — `color: inherit`
 flattens them; employer CSS is unbounded and a near-black heading would land dark-on-dark. audit-chroma
 reports `flattened`; intended. */
  [class*="vacancy-branded-user-content"] strong,
  [class*="vacancy-branded-user-content"] b,
  [class*="vacancy-branded-user-content"] em,
  [class*="vacancy-branded-user-content"] font,
  [class*="vacancy-branded-user-content"] span {
    background-color: transparent !important; }
  /* search-term highlight: keep the "matched word" meaning, dark amber */
  span.highlighted, mark, .bloko-text_highlighted {
    background-color: #4a3a12 !important; color: #f0d58a !important; }
  /* The branded-vacancy photo widget ships a hardcoded WHITE "backplate" and a #eef1f7 loading skeleton under
 the employer banner. Both are normally hidden — the loaded image covers the plate exactly — but until it
 arrives (or if it's a transparent PNG / fails) a 930px near-white block sits on the page. Dark both; the
 plate holds no text (the content variant keeps its own elevated surface). */
  [class*="backplate-module_backplate"] {
    background-color: #1c2128 !important; }
  [class*="picture-widget-module_loader"] {
    background-color: #21262d !important; }

  /* ---- Employer / company page ---- */
  [data-qa="employer-chameleon-header"], [class*="employer-header"],
  [data-qa="company-header-title"], .employer-sidebar, .employer-info {
    background-color: transparent !important; }
  [data-qa="company-header-title-name"], [data-qa="company-header-title"] {
    color: #e6edf3 !important; }
  [data-qa="employer-page-description"], .employer-description,
  [class*="employer-page"] { color: #c4cdd6 !important; }
  /* company logo: never tint the image */
  [data-qa="company-logo-image"], [data-qa="company-logo-image"] img,
  [class*="company-logo"] img { background-color: transparent !important; }

  /* ---- Ratings / reviews stars: keep them visible (preserve semantic) ---- */
  [data-qa="employer-reviews-stars"], [data-qa="employer-review-small-widget-total-rating"],
  [class*="rating-stars"] { color: inherit; }

  /* ---- Tabs ---- */
  [data-qa="tab-list"], [class*="magritte-tab"], .bloko-tabs__item {
    background-color: transparent !important; border-color: #2d333b !important; }
  /* Magritte tabs are PILLS now: the current tab carries `magritte-tab_selected` and a solid dark pill + white
 label — no `-active` class. The old `[class*="active"]` selectors matched nothing, so the blanket
 transparent-bg rule erased the only "you are here" cue. */
  [class*="magritte-tab_selected"] {
    background-color: #30363d !important; }
  [class*="magritte-tab_selected"] [class*="magritte-tab-content"],
  [class*="magritte-tab_selected"] [class*="magritte-tab-label"] {
    color: #ffffff !important; }
  /* Legacy bloko tabs (/partners "Варианты партнёрства" switcher) ride a rounded `bloko-tabs-holder` strip
 (#edeff0), with the current tab marked by hh blue on the label AND a ::after underline the `* {
 border-color }` blanket cannot reach. Unselected labels are near-black #2a3137 <button>s our typography
 never lifts — darkening the strip alone would hide them. Take all four together; lift the blue to the theme
 accent. Scroll glares are light gradients keyed to the strip's colour. */
  .bloko-tabs-holder { background-color: #21262d !important; }
  .bloko-tabs-left-glare, .bloko-tabs-right-glare {
    background-image: none !important; }
  .bloko-tabs__item_active { color: #5fb0e6 !important; }
  .bloko-tabs__item_active::after { border-bottom-color: #5fb0e6 !important; }
  [class*="magritte-tab"]:not([class*="selected"]), .bloko-tabs__item:not(.bloko-tabs__item_active) {
    color: #c4cdd6 !important; }
  /* below the resting arm above, which it ties at 0-2-0 */
  .bloko-tabs__item:hover, .bloko-tabs__item:focus, .bloko-tabs__item:active {
    color: #9bd4ff !important; }
  /* A tab's LABEL is a `magritte-text_style-primary` span in both states — the component carries the state
 (selected #fff / unselected #6a7885). Our heading rule matches `magritte-text` + `primary` and painted both
 #e6edf3, so "Резюме"/"Компании" read as bright as the current "Вакансии". Mute the unselected label.
 Anchored on `magritte-tab___`: a bare `magritte-tab` prefix also matches the inner `tab-content` wrapper,
 which carries no state class — the selected label would grey too. */
  [class*="magritte-tab___"]:not([class*="selected"]) [class*="magritte-tab-label"],
  [class*="magritte-tab___"]:not([class*="selected"]) [class*="magritte-tab-label"] [class*="magritte-text"] {
    color: #8b949e !important; }
  /* …and give the unselected tab its hover back. Natively every tab carries a pill (#f1f4f9 → #dce3eb under the
 pointer); the transparent rule above — needed so only the current tab reads filled — took the hover with
 it. Restore a lift clearly below the selected pill's #30363d. `:not()` + `:hover` clears the transparent
 rule's 0-1-0. */
  [class*="magritte-tab___"]:not([class*="selected"]):hover {
    background-color: #21262d !important; }
  [class*="magritte-tab___"]:not([class*="selected"]):hover [class*="magritte-tab-label"],
  [class*="magritte-tab___"]:not([class*="selected"]):hover [class*="magritte-tab-label"] [class*="magritte-text"] {
    color: #c4cdd6 !important; }

  /* ---- Tables (within descriptions) ---- */
  table { background-color: transparent !important; }
  th { background-color: #1c2128 !important; color: #e6edf3 !important; }
  td, th { border-color: #2d333b !important; color: #c4cdd6 !important; }

  /* ---- Login / auth page ---- */
  /* The full-page auth backdrop is a decorative illustration baked on WHITE (background-IMAGE — invisible to
 bg-color scans; `lightBgImages` only flags gradients, so audit-theme reports total=0 on a fully white login
 page). Drop it so the dark base shows behind the sign-in card. Both spellings ship:
 `wrapper-with-image--<hash>` does NOT contain `wrapper-image`. */
  [class*="wrapper-image"], [class*="wrapper-with-image"],
  [class*="account-login-page"] {
    background-image: none !important; background-color: #14181d !important; }
  /* The mobile standalone auth layout wraps the page in a full-viewport "light-page" div (hardcoded #f4f6fb)
 BEHIND the dark auth overlay. It is occluded, but the overlay has a history of white-frame bleed at the
 open transition — dark the backing to the page base so nothing light can show through an edge. */
  [class*="light-page"] {
    background-color: #14181d !important; }
  /* the small "mode-icon" avatars (employer info badges: location / registration) ship a black glyph on a light
 neutral disc — darken the disc and lift the glyph (its fill is currentColor, which resolves to black) so
 the icon stays legible on the dark card */
  [class*="magritte-avatar_mode-icon"][class*="magritte-avatar_style-secondary"] {
    background-color: #21262d !important; }
  [class*="magritte-avatar_mode-icon"][class*="magritte-avatar_style-secondary"] svg,
  [class*="magritte-avatar_mode-icon"][class*="magritte-avatar_style-secondary"] svg path {
    color: #b8c0c9 !important; fill: currentColor !important; }
  /* the ACCENT variant of those mode-icon discs (e.g. the employer "Сайт" website-link badge) ships a pale-blue
 disc — dark it to a blue-tinted surface; its accent-blue glyph stays its brand colour and reads on top. */
  [class*="magritte-avatar_mode-icon"][class*="magritte-avatar_style-accent-secondary"] {
    background-color: #1f3550 !important; }
  /* The anonymous avatar (resume cards, login role picker) is a DAY-only raster:
 `url(…/{male,female,undefined,city}-day__min_<hash>.webp)`, near-white #eef1f7. Nothing a scan reads (own
 bg transparent, plate is image paint), so bright 96px tiles glare down the list. The night asset needs a
 build-hashed URL, so invert the day art: hue-rotate cancels the warm cast, contrast/brightness keep the
 silhouette separable from its plate. `data-qa^="placeholder-"` covers future variants; the leaf holds no
 children, so the sibling "online" badge pseudo stays outside. */
  [class*="magritte-avatar_mode-placeholder"] > [data-qa^="placeholder-"] {
    filter: invert(1) hue-rotate(180deg) contrast(0.8) brightness(1.25) !important; }
  /* The "IT-аккредитация" chip (~24px disc, next to the rating) ships a light disc with a BLACK currentColor
 "it" glyph — audit-blind (under the scan floor) and a bright spot on dark. Dark the disc, lift the glyph. */
  [data-qa="accredited-it-employer-icon"] {
    background-color: #21262d !important; }
  [data-qa="accredited-it-employer-icon"] svg,
  [data-qa="accredited-it-employer-icon"] svg path {
    color: #b8c0c9 !important; fill: currentColor !important; }
  /* The "hh карьера" lockup on /services cards is an external background-IMAGE SVG with a `fill="#000"`
 wordmark — invisible on our dark card while every scan passes (element bg transparent, black lives in image
 paint). Can't recolour per-shape from CSS, so invert: the wordmark comes back white, hue-rotate returns the
 brand disc to red (saturate deepens the salmon a bare inversion leaves). */
  [class*="careerhhru--"] {
    filter: invert(1) hue-rotate(180deg) saturate(3) !important; }
  /* /employer landing's product mockups are hh UI screenshots as a raster (`vacancies-*` / `candidates-*`
 webp): ~85% white with near-black ink, on an element whose bg is already dark — scans pass while two
 470x175 white slabs glare. The ink is content, so only inverting LIGHTNESS works; hue-rotate keeps the
 accents, reduced contrast stops the ink blowing out to white. `contain` letterboxes, so the element bg must
 go transparent or the filter inverts it into a light band. The A/B `alt-image` variant is flat blue SVG
 that must stay OUT. Match the un-hashed module prefix. */
  [class*="price-card-image--"]:not([class*="alt-image--"]) {
    filter: invert(1) hue-rotate(180deg) contrast(0.75) brightness(1.1) !important;
    background-color: transparent !important; }

  /* ---- Cookie / consent informer (kill the bright bar; click-dismiss in real use) ---- */
  [data-qa="cookies-policy-informer"], .cookies-policy-informer {
    background-color: #0d1117 !important; border-color: #2d333b !important; color: #c4cdd6 !important; }
  /* Legacy Bloko toast (mobile "Ваш регион — Москва?" prompt and other transient notices) ships a hardcoded
 WHITE `bloko-notification__plate`. Desktop uses the native-dark magritte tooltip, so this only surfaces on
 the mobile/legacy path — a bright banner over the dark SERP. Dark the plate; title maps light, accent
 buttons and info glyph keep their hues. */
  [class*="bloko-notification__plate"], [class*="bloko-notification__wrapper"] {
    background-color: #1c2128 !important; border-color: #2d333b !important; }
  /* "Удобнее в приложении" smart banner above the header: mounts only under an iOS/Android UA and only after
 the cookie informer sharing its slot is dismissed, so a 390px desktop resize never renders it. Wrapper is
 hashed — `data-qa` is the stable hook. Hardcoded #f4f6fb under our light title and pale ✕ = a white bar
 with near-invisible text. Elevated value: it sits ABOVE the header, which is #0d1117. The app-icon raster
 stays untouched. */
  [data-qa="app-smartbanner"] {
    background-color: #1c2128 !important; border-color: #2d333b !important; }
  /* Phone bottom tab bar (app-shell nav): hardcoded `background:#fff` on a full-width fixed z-1040 bar.
 `tapbar--` (double dash) is the base bar only — `tapbar-item--` / `tapbar-animated-container--` never
 contain it. The ACTIVE tab is the only one hh emphasises (#000 vs #8293a2); the blanket link ink paints
 every tab the same accent, so the current tab stops reading selected. Three arms: bare text node, wrapped
 span, and `a…` to outrank `a span` link ink. */
  [class*="tapbar--"] {
    background-color: #1c2128 !important; border-color: #2d333b !important; }
  [class*="tapbar-item--"],
  [class*="tapbar-item--"] span,
  a[class*="tapbar-item--"] span { color: #8b949e !important; }
  [class*="tapbar-item-active--"],
  [class*="tapbar-item-active--"] span,
  a[class*="tapbar-item-active--"] span { color: #e6edf3 !important; }

  /* ---- Footer ---- */
  /* `footer-services--<hash>` is a full-width promo band nested INSIDE the <footer> (/employers_rating, /price
 …) with its own hardcoded #eef1f7. A child's bg wins over the ancestor footer rule, so it stayed a 1280×233
 white stripe with near-invisible light copy on it. */
  [class*="footer-nav"], [class*="footer-app-banner"], [class*="footer-services"],
  .supernova-footer,
  footer, .footer, [data-qa="footer"] {
    background-color: #0d1117 !important; border-color: #2d333b !important; }
  [class*="footer-nav"] a, .supernova-footer a, footer a { color: #8ab4d8 !important; }
  [class*="footer-nav"] span, footer span, .copyright { color: #8b949e !important; }

  /* ---- Banners / ad surrounds: dark, no bright leaks (don't theme iframe content) ---- */
  [class*="banner-place"], [class*="footer-app-banner-redesign"], .HH-Banners {
    background-color: #14181d !important; border-color: #2d333b !important; }
  /* App-download QR codes (footer "Мобильное приложение" block + banner) are transparent images of BLACK
 modules — on our dark page they are black-on-dark while every audit passes (element bg IS our dark value,
 module art is raster/SVG paint). A QR needs a light quiet zone, so give the containers a white backing. NB:
 the "Вакансии в мессенджере" QR is a .webp with white baked in and needs nothing. */
  [class*="footer-app-banner-redesign-qr-image"], [class*="qr-code--"] {
    background-color: #ffffff !important; }
  /* Both QR blocks now nest the code inside a Magritte CARD, and the generic card rule paints it #21262d — an
 opaque dark tile ON TOP of the white backing, so the code cannot scan. Every audit still passes: the
 `qr-code--` bg IS #ffffff, the card legitimately dark, the modules image paint. Give the card the same
 white quiet zone — it holds nothing but the code. `-qr--` keeps the app-banner arm to the base wrapper
 (`-qr-image--` never contains the double dash). */
  [class*="qr-code--"] [class*="magritte-card"],
  [class*="footer-app-banner-redesign-qr--"] [class*="magritte-card"] {
    background-color: #ffffff !important; }

  /* ---- "Vacancies on map" button (shipped light) ---- */
  [class*="map-button"] {
    background-color: #21262d !important; border-color: #2d333b !important; }
  /* the label rides a translucent white glass pill (rgba(255,255,255,.68) + blur) over the map preview —
 audit-blind (exactly 40px, under the floor) and our light label reads light-on-light. Flip the glass dark. */
  [class*="map-button"] [class*="button--"] {
    background-color: rgba(13, 17, 23, 0.72) !important; }
  /* vacancy detail "Где предстоит работать" Yandex map: the raster tiles sit on a WHITE map-bg pane (and the
 container itself is light) — when tiles are slow/partial that pane glares white. Dark the container + ymaps
 base pane so any uncovered area reads dark; the opaque tiles still paint over it. */
  .vacancy-address-map, [class*="vacancy-address-map"],
  [class*="ymaps"][class*="-map-bg"], [class*="ymaps"][class*="-ground-pane"] {
    background-color: #1c2128 !important; }
  /* The map-bg pane also carries the "no tile here yet" checker as an inline base64 background-IMAGE painting
 OVER the dark colour above — every uncovered area (the whole widget until tiles arrive, any gap while
 panning) stays a bright dotted panel. bg-COLOR scans read our #1c2128. Drop the pattern; loaded tiles are
 opaque. */
  [class*="ymaps"][class*="-map-bg"] {
    background-image: none !important; }

  /* ---- Pagination / "show more" ---- Natively only the CURRENT page carries a filled pill. Painting the whole
 component one grey turned the pager into identical chips and erased the "you are here" cue. Keep links
 bare; give the selected page its pill. */
  [class*="magritte-number-pages-wrapper"],
  [class*="magritte-number-pages-container"],
  [class*="magritte-number-pages-item"],
  [class*="magritte-number-pages-ellipsis"],
  [class*="magritte-number-pages-action"] {
    background-color: transparent !important; color: #c4cdd6 !important; }
  [data-qa^="pager-"] {
    background-color: transparent !important; color: #c4cdd6 !important; }
  [class*="magritte-number-pages-action"]:hover {
    background-color: #21262d !important; }
  [class*="magritte-number-pages-action"][class*="selected"] {
    background-color: #30363d !important; color: #ffffff !important; }

  /* ---- Sticky bottom action bar ("Откликнуться") ---- hardcoded WHITE, and only position:fixed once you
 scroll, so top-of-page scans never see it. Dark the floating bar; buttons inside already map dark/accent. */
  [class*="magritte-action-bar"] {
    background-color: #0d1117 !important; border-color: #2d333b !important; }
  /* The same action bar also closes filter drops, modals and bottom sheets, where it sits on the panel's own
 surface (natively white on white). It must take the panel colour there, or it renders as a dark square
 behind the rounded button. */
  [class*="magritte-drop___"] [class*="magritte-action-bar"],
  [class*="magritte-modal"] [class*="magritte-action-bar"],
  [class*="magritte-visual-container"] [class*="magritte-action-bar"] {
    background-color: #1c2128 !important; }

  /* The /services "Популярное сейчас" section ships a hardcoded light-lavender (#f7f4ff) full-width wrapper
 behind the dark service cards — a raw hex the token remap misses. Dark it to the page base. */
  [class*="popular-services-wrapper"] {
    background-color: #14181d !important; }

  /* ---- Blog / articles (/articles hub + /article/<id> CMS body) ---- (1) The "cms-aside" callout and
 "cms-album" placeholders ship a hardcoded #f9f9f9 panel. The aside's label is a dark #333 on a tag our
 typography never matches (would go dark-on-dark). Dark the surface, force the text light. */
  [class*="cms-aside"], [class*="cms-album__placeholder"], [class*="cms-album__frame"] {
    background-color: #1c2128 !important; border-color: #2d333b !important; }
  [class*="cms-aside"], [class*="cms-aside"] * { color: #c4cdd6 !important; }
  /* (2) Blog category chips (`tag--<hash>` + `tag-<colour>--<hash>`) ship a PALE tint (#fdede9 … #f4f6fb) with
 no text colour — the label inherits dark body text, which our blanket div rule flattened to light grey →
 light-on-pale. Dark each colour to a tinted surface, lift the label so the colour coding survives. Both
 classes required, so ONLY the blog pills match, never a magritte/bloko tag. */
  [class*="tag--"][class*="tag-red--"] { background-color: #3a231e !important; }
  [class*="tag--"][class*="tag-red--"], [class*="tag--"][class*="tag-red--"] * { color: #ff8a7a !important; }
  [class*="tag--"][class*="tag-orange--"] { background-color: #33261a !important; }
  [class*="tag--"][class*="tag-orange--"], [class*="tag--"][class*="tag-orange--"] * { color: #fdb972 !important; }
  [class*="tag--"][class*="tag-yellow--"] { background-color: #33261a !important; }
  [class*="tag--"][class*="tag-yellow--"], [class*="tag--"][class*="tag-yellow--"] * { color: #e6c766 !important; }
  [class*="tag--"][class*="tag-green--"] { background-color: #16301f !important; }
  [class*="tag--"][class*="tag-green--"], [class*="tag--"][class*="tag-green--"] * { color: #57d98a !important; }
  [class*="tag--"][class*="tag-blue--"] { background-color: #1f3550 !important; }
  [class*="tag--"][class*="tag-blue--"], [class*="tag--"][class*="tag-blue--"] * { color: #7cc3f0 !important; }
  [class*="tag--"][class*="tag-violet--"] { background-color: #241d33 !important; }
  [class*="tag--"][class*="tag-violet--"], [class*="tag--"][class*="tag-violet--"] * { color: #c3a6f5 !important; }
  [class*="tag--"][class*="tag-grey--"] { background-color: #21262d !important; }
  [class*="tag--"][class*="tag-grey--"], [class*="tag--"][class*="tag-grey--"] * { color: #c4cdd6 !important; }

  /* ---- Производственный календарь (/calendar) ---- Legacy page, body-inlined stylesheet, no tokens. (1)
 `_other` filler cells are #fff natively — clear. (2) `_day-off` (#ffbebe) / `_shortened` (#feef7b) ARE the
 colour key, with a black day number we lift to light grey → light-on-pale: dark tint of the same hue +
 readable number, legend swatches matched. (3) The overview label masks its dotted leader with a #fff span —
 must match the page base. (4) Tooltip + row hover are white pointer-only panels; quarter rows re-assert
 #fff with their own !important (hence the `tr` compound) and must stay below the row-hover arm. */
  .calendar-list__numbers__item_other {
    background-color: transparent !important; }
  .calendar-list__numbers__item_day-off,
  .calendar-info-explanation__color_red {
    background-color: #4a2c25 !important; }
  .calendar-list__numbers__item_day-off { color: #ff8a7a !important; }
  .calendar-list__numbers__item_day-off:hover {
    background-color: #5c3830 !important; }
  .calendar-list__numbers__item_shortened,
  .calendar-info-explanation__color_yellow {
    background-color: #4a3a12 !important; }
  .calendar-list__numbers__item_shortened { color: #f0d58a !important; }
  .calendar-list__numbers__item_shortened:hover {
    background-color: #5c4917 !important; }
  .calendar-list__overview-label > span {
    background-color: #14181d !important; }
  .calendar-hint { background-color: #21262d !important; }
  .calendar-norms tr:hover { background-color: #21262d !important; }
  tr.calendar-norms-heading:hover, tr.calendar-norms-separator:hover {
    background-color: transparent !important; }
  .calendar-norms-separator td::before {
    background-color: #2d333b !important; }

  /* ---- Legal / rules documents (/conditions, /terms) ---- The `hh-rules` sidebar is a stack of white cards
 (banner, expand-all toggle, archive/nav links) our forced light body text sits on. The toggle's off track
 is a light pill; its knob and the ON track's green are correct as-is. */
  .hh-rules__banner, .hh-rules__all, .hh-rules__button, .hh-rules__archive-link {
    background-color: #1c2128 !important; }
  .hh-rules__banner-button { background-color: #21262d !important; }
  .hh-rules__banner-button:hover { background-color: #2d333b !important; }
  a.hh-rules__banner-button--blue {
    background-color: #1f3550 !important; color: #5fb0e6 !important; }
  a.hh-rules__banner-button--blue:hover { background-color: #24406b !important; }
  .hh-rules__control:not(.hh-rules__control--active) {
    background-color: #3a424c !important; }

  /* ---- "Безопасный HeadHunter" (/safety) ---- Bespoke marketing page (own `cx_` module) drawn for a white
 sheet: the pale-blue band and the article sheet are painted by PSEUDO-elements, so an element-bg scan reads
 the page themed while every word renders on white. The advice cards rotate green/blue/ violet by position
 (not class), so the rotation needs the same nth-child arithmetic; the screenshot frames, arrows and
 media-fade gradient are white chrome. */
  .cx_content::before, .cx_insetContent, .cx_insetContent::before {
    background-color: #14181d !important; }
  .cx_signsItem { background-color: #1f3550 !important; }
  .cx_signsItem:nth-child(4n+1) { background-color: #16301f !important; }
  .cx_signsItem:nth-child(4n+3) { background-color: #241d33 !important; }
  .cx_signsItem_example_block, .cx_scammersItems .slick-arrow {
    background-color: #21262d !important; }
  .cx_scammersItem_media::after { background-image: none !important; }

  /* ---- Блог (/blog) ---- A separate Next.js app with its own chrome — the supernova header rules never reach
 it, so its sticky `Header_header--<hash>` bar stays white under already-light nav labels. Runs an older
 Magritte set (-v24-3-0, icon-primary #000), so the search magnifier is black — scoped to the header's
 magritte icons so the logo's own fills are untouched. */
  header[class*="Header_header"],
  [class*="Header_mobileMenuContent"] {
    background-color: #0d1117 !important; border-color: #2d333b !important; }
  header[class*="Header_header"] [class*="magritte-icon"] {
    color: #c4cdd6 !important; }
  [class*="Footer_separator"] { background-color: #2d333b !important; }
  /* The Дзен mark is the one social icon that hardcodes its fill instead of inheriting currentColor — alone
 near-black on the dark footer. It's a single evenodd path (tile with the star punched out), so lifting the
 fill gives the inverted mark the rest of the row shows. Exact-value match: no other icon uses it. */
  [class*="Footer_socialLinks"] path[fill="#202022"] { fill: #c4cdd6 !important; }

  /* Article body panels. The blog's own modules hardcode hh's light greys; the three banner cards read
 `--color-neutral-secondary`/ -tertiary, which the app never declares — the light literal in the var()
 fallback paints, so the class must be named. `ColorBlock` is a highlight callout: kept a warm tint so it
 still reads as one. Enumerated from the blog's own stylesheets, so other articles are covered too. */
  [class*="AuthorQuote_authorQuote"], [class*="ArticleQuote_articleQuote"],
  [class*="BannerEnd_cardContainer"], [class*="BannerSetka_cardContainer"],
  [class*="BannerSocial_cardContainer"], [class*="ArticleContent_thumbnail"],
  [class*="Baner_tag"], [class*="Announcement_tag"],
  [class*="ArticleContent_contentLeft"] table tr:nth-child(2n) {
    background-color: #1c2128 !important; }
  [class*="BannerSocial_linkButton"] { background-color: #21262d !important; }
  [class*="BannerSocial_linkButton"]:hover { background-color: #2d333b !important; }
  [class*="ColorBlock_colorBlock"] { background-color: #2e2611 !important; }
  /* The CMS lets the author pick each ColorBlock's plate and outline as INLINE colours; the rule above darkens
 the module default (#fff3cc). The dominant authored variant is a transparent plate with an hh-red outline,
 and a lilac/purple one also ships — keep each its own shape instead of painting every block amber. The
 border softener is !important, so the inline outline must be restated per value. */
  [class*="ColorBlock_colorBlock"][style*="background-color:#00000000"] {
    background-color: transparent !important; }
  [class*="ColorBlock_colorBlock"][style*="border-color:#FF4D3A"],
  [class*="ColorBlock_colorBlock"][style*="border-color:#ff4d3a"] {
    border-color: #ff4d3a !important; }
  [class*="ColorBlock_colorBlock"][style*="background-color:#F7F4FF"],
  [class*="ColorBlock_colorBlock"][style*="background-color:#f7f4ff"] {
    background-color: #241d33 !important; color: #c4cdd6 !important; }
  [class*="ColorBlock_colorBlock"][style*="border-color:#9054EA"],
  [class*="ColorBlock_colorBlock"][style*="border-color:#9054ea"] {
    border-color: #b48cf0 !important; }
  /* The right-rail vacancy banner's title sits over the pale top of a fixed raster illustration, so the ink
 must stay dark there. The label carries `magritte-text_style-primary`, so the arm needs the same
 two-attribute weight as the typography rule it overrides. */
  [class*="VacancyBanner_text"],
  [class*="VacancyBanner_text"] [class*="magritte-text"] {
    color: #14181d !important; }

  /* Case-study articles ship their layout as an inline <style> in the CMS body: a light `#f1f4f9` panel per
 metric card with `color:#000` copy our light ink overrides, so the panel is the half that has to move. */
  .case-key-data-block, .case-metric-card {
    background-color: #1c2128 !important; }

  /* ---- Партнёрам (/partners) ---- Another white-sheet page with its own module: the keyword pills and
 "Инструменты" cards are light panels our forced light copy sits on, and each full-width band is painted by
 a `::before` an element-bg scan cannot see. */
  .partners-tips__tip { background-color: #21262d !important; }
  .partners-tools__tool { background-color: #1c2128 !important; }
  .partners-tools::before, .partners-howto::before {
    background-color: #14181d !important; }

  /* ---- Мобильные приложения (/mobile) ---- Own `mob__hh__` module. Every section paints its band on a
 `.mob__hh__background` child, the curved seam between bands on a `.mob__hh__wave` layer (SVG on one
 section, raster elsewhere) with both colours baked in — the seam drops whenever a band moves. The band
 class is shared with the natively-dark hero and bottom link band, hence the per-section arms. `#311791` is
 hh's own purple for the search band (pale only on desktop). Mock-ups, notification cards and QR keep their
 light plates — they depict the app. */
  .mob__hh__section__beside > .mob__hh__background:not(.mob__hh__wave),
  .mob__hh__section__declare > .mob__hh__background:not(.mob__hh__wave) {
    background-color: #14181d !important; }
  .mob__hh__section__search > .mob__hh__background:not(.mob__hh__wave) {
    background-color: #311791 !important; }
  .mob__hh__section__find-job > .mob__hh__wave,
  .mob__hh__section__beside > .mob__hh__wave,
  .mob__hh__section__search > .mob__hh__wave {
    background-image: none !important; }
  .mob__hh__section__find-job .mob__hh__wave path,
  .mob__hh__section__beside .mob__hh__wave path {
    fill: #14181d !important; }
  /* The store CTA is an <a> carrying the solid-button class, so the site-wide link ink lands on the label
 instead of the button's own white. */
  a.mob__hh__button { color: #ffffff !important; }

  /* ---- Карьерный маркетплейс (/mentors) ---- A micro-frontend (mentors-front.hh.ru) under
 .MentorsFront-ReactRoot, on the v24-7-1 tokens above. Two surfaces are hardcoded in its own module CSS: the
 hero band, a full-bleed light gradient as a background-IMAGE (a bg-COLOUR rule alone leaves it painted),
 and the "Шаг N" pills (#fff plate, label inheriting body ink). */
  .MentorsFront-ReactRoot > div[class*="container--"] {
    background-color: #14181d !important;
    background-image: none !important; }
  .MentorsFront-ReactRoot div[class*="tag--"] {
    background-color: #21262d !important; }
  /* The hero H1 marks one word in hh red via a module `red--<hash>` span; the tmpl-free body ink would flatten
 it to the heading grey. */
  .MentorsFront-ReactRoot span[class*="red--"] {
    color: #ff4d3a !important; -webkit-text-fill-color: #ff4d3a !important; }

  /* ---- Рекламные продукты (/article/promoproducts) ---- The "startic" CMS renderer's Vite app under
 #cmsFrontendAppRoot has its styles in an inline <style> in the BODY — later in document order than our
 sheet, so only !important wins. Classes are `_<name>_<hash>_<line>`: match the NAME, never the hash.
 Bands/cards are hardcoded #f1f4f9 / #fff literals, unreachable by the v18-1-0 block; the band arm CLEARS
 the colour so a nested wrapper keeps its plate. Icons are single-colour CDN SVGs on an empty
 `content:url()` pseudo — what makes inverting them safe. */
  #cmsFrontendAppRoot [class*="_container_"],
  #cmsFrontendAppRoot [class*="_items_"],
  #cmsFrontendAppRoot [class*="_infoBlock_"],
  #cmsFrontendAppRoot [class*="_slide_"] {
    background-color: transparent !important;
    background-image: none !important; }
  #cmsFrontendAppRoot [class*="_item_"],
  #cmsFrontendAppRoot [class*="_whiteSquare_"],
  #cmsFrontendAppRoot [class*="_smallContainer_"],
  #cmsFrontendAppRoot [class*="_formContainer_"],
  #cmsFrontendAppRoot [class*="_chooseBlock_"],
  #cmsFrontendAppRoot [class*="_sliderInfoBlockWhite_"],
  #cmsFrontendAppRoot [class*="_addIcon_"],
  #cmsFrontendAppRoot .swiper-button-next,
  #cmsFrontendAppRoot .swiper-button-prev {
    background-color: #1c2128 !important; }
  #cmsFrontendAppRoot .swiper-fade {
    background-color: rgba(20, 24, 29, 0.7) !important; }
  #cmsFrontendAppRoot [class*="_addIcon_"]::before,
  #cmsFrontendAppRoot [class*="_addIcon_"]::after,
  #cmsFrontendAppRoot [class*="_itemHeader_"]::after,
  #cmsFrontendAppRoot .swiper-button-next::before,
  #cmsFrontendAppRoot .swiper-button-prev::before {
    filter: invert(1) !important; }
  /* The app keeps its own saturated fills (blue stat tiles, expert pills, the blue ::before a highlight word
 draws), so labels on them must stay #fff or the body ink lands on brand colour. The highlight word is the
 only bare <span> carrying a `_container_` class. */
  #cmsFrontendAppRoot span[class*="_container_"],
  #cmsFrontendAppRoot [class*="_sliderInfoBlockOne_"],
  #cmsFrontendAppRoot [class*="_sliderInfoBlockOne_"] *,
  #cmsFrontendAppRoot [class*="_sliderInfoBlockTwo_"],
  #cmsFrontendAppRoot [class*="_sliderInfoBlockTwo_"] *,
  #cmsFrontendAppRoot [class*="_moreContainer_"],
  #cmsFrontendAppRoot [class*="_currentTitleContainer_"] {
    color: #ffffff !important; }
  /* The solution-picker pills are the one plate in this app that encodes state (#f1f4f9 unselected / #000
 selected); the band arm above clears both, so the two have to be re-split here. */
  #cmsFrontendAppRoot [class*="_sliderSelectorList_"] > [class*="_container_"] {
    background-color: #21262d !important; }
  #cmsFrontendAppRoot [class*="_sliderSelectorList_"] > [class*="_active_"] {
    background-color: #1f3550 !important; }
  #cmsFrontendAppRoot [class*="_sliderSelectorList_"] > [class*="_active_"],
  #cmsFrontendAppRoot [class*="_sliderSelectorList_"] > [class*="_active_"] * {
    color: #ffffff !important; }

  /* ---- hh бизнес (/hrmobile) ---- A brand-purple page. Two labels sit on a plate hh paints white and colours
 purple — correct there — so only the ink comes back; the third `.hh-business-text`, on the dark hero, stays
 with the body ink. */
  .hh-business__main-subtitle .hh-business-text { color: #7945c1 !important; }
  .qr-text { color: #3a1da1 !important; }

  /* ---- Chatik messenger widget (header chat bubble) ---- The whole widget chrome is driven by `--chatik-*`
 custom properties that hh never declares anywhere, so every consumer falls back to its light literal
 (`#f1f4f9` header bar, `#ffffff` iframe backdrop, `#dce3eb` border, `#000` icons). Declaring them is the
 only hook: the rules themselves live in hh's own sheet and the panel body is the cross-frame chatik app. */
  :root {
    --chatik-header-background: #1c2128;
    --chatik-background: #14181d;
    --chatik-border-color: #2d333b;
    --chatik-icon-color: #c4cdd6;
    --chatik-loader-color: #5fb0e6;
    --chatik-shadow-color: rgba(0, 0, 0, 0.6); }

  /* ---- Misc surfaces hh paints white directly ---- */
  [style*="background-color: rgb(255, 255, 255)"],
  [style*="background:#fff"], [style*="background: #fff"],
  [style*="background-color:#fff"] { background-color: #1c2128 !important; }
  /* legacy near-black text hardcoded inline (#1b1b1b / #2a3137 / #000) */
  [style*="color: rgb(27, 27, 27)"], [style*="color: rgb(42, 49, 55)"],
  [style*="color: rgb(0, 0, 0)"], [style*="color:#000"] { color: #c4cdd6 !important; }

  hr { border-color: #2d333b !important; }
  ::selection { background-color: #2f6fb8 !important; color: #ffffff !important; }
}
